#[derive(Debug, Clone, Copy)]
pub enum EvidenceKind {
    Auto,
    File,
    Folder,
    Image,
}

impl EvidenceKind {
    pub fn parse(value: &str) -> Result<Self> {
        match value.to_ascii_lowercase().as_str() {
            "auto" => Ok(Self::Auto),
            "file" => Ok(Self::File),
            "folder" => Ok(Self::Folder),
            "image" => Ok(Self::Image),
            other => Err(anyhow!("unsupported evidence kind: {other}")),
        }
    }
}

